    while (bb.hasRemaining()) {
        byte b = bb.get();
        if ((b & 0x80) == 0) {
            sb.append((char) b);
        } else if ((b & 0xE0) == 0xC0) {
            if (bb.remaining() < 1) {
                return i;
            }
            byte b2 = bb.get();
            sb.append((char) (((b & 0x1F) << 6) | (b2 & 0x3F)));
        } else if ((b & 0xF0) == 0xE0) {
            if (bb.remaining() < 2) {
                return i;
            }
            byte b2 = bb.get();
            byte b3 = bb.get();
            sb.append((char) (((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F)));
