public static int nullSafeHashCode(long[] array) {
    if (array == null) {
        return 0;
    }
    int hash = HASH_MULTIPLIER;
    for (long l : array) {
        hash = Math.multiplyExact(hash, PLATFORM_MULTIPLIER) ^ hash(l);
    }
    return hash;
}

