public String format(LoggingEvent event){
    // Assuming the conversion pattern is stored in a variable
    String conversionPattern = "%d{yyyy-MM-dd HH:mm:ss} %-5p %c{1}:%L - %m%n";

    // Create a SimpleDateFormat object to parse the conversion pattern
    SimpleDateFormat simpleDateFormat = new SimpleDateFormat();
    simpleDateFormat.applyPattern(conversionPattern);

    // Extract the necessary information from the event object
    Date date = event.getTimeStamp();
    String level = event.getLevel().toString();
    String loggerName = event.getLoggerName();
    int lineNumber = event.getLocationInformation().getLineNumber();
    String message = event.getMessage().toString();

    // Format the string according to the conversion pattern
    return simpleDateFormat.format(date) + " " + level + " " + loggerName + ":" + lineNumber + " - " + message;
}
