        throw new IllegalArgumentException("Invalid input parameters");
    }

    for (int i = 0; i < end; i++) {
        char c = headerPart.charAt(i);
        if (c == '\r' && i + 1 < end && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
