private int parseEndOfLine(String headerPart, int end) {
    int index = end - 1;
    while (index >= 0) {
        char ch = headerPart.charAt(index);
        if (ch == '\n') {
            if (index == 0 || headerPart.charAt(index - 1) != '\r') {
                return index;
            }
        }
        index--;
    }
    return -1;
}
