private static final javax.swing.SwingWorker<Void, LogRecord> worker = new javax.swing.SwingWorker<Void, LogRecord>() {
    @Override
    protected Void doInBackground() throws Exception {
        for (LogRecord lr : queue) {
            // Process the log record in the SwingEvent thread
            processLogRecord(lr);
        }
        return null;
    }

    @Override
    protected void process(java.util.List<LogRecord> chunks) {
        for (LogRecord lr : chunks) {
            // Process the log record in the SwingUI thread
            displayLogRecord(lr);
        }
    }
};

public void addMessage(final LogRecord lr) {
    if (javax.swing.SwingUtilities.isEventDispatchThread()) {
        processLogRecord(lr);
    } else {
        queue.add(lr);
        // Start the worker if it's not already running
        worker.execute();
    }
}

