private static byte[] encodeVarint32(int value) {
    byte[] result = new byte[5];
    int i = 0;
    while ((value & 0x80) != 0) {
        result[i++] = (byte) (value & 0x7F | 0x80);
        value >>>= 7;
    }
    result[i] = (byte) (value & 0x7F);
    return Arrays.copyOf(result, i + 1);
}
