public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message);
    buffer.buffer().clear();
    try {
        CodedOutputByteBufferWriter writer = CodedOutputByteBufferWriter.newInstance(buffer.buffer(), 0, buffer.buffer().length);
        writer.writeVarint32NoTag(size);
        schema.write(message, writer);
        buffer.buffer().flip();
        out.write(buffer.buffer().array(), buffer.buffer().position(), buffer.buffer().remaining());
        return size;
    } catch (IOException e) {
        throw e;
    } finally {
        buffer.resetBuffer();
    }
}
