}

List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long fetchDuration = 30000; // Example value for FETCH_DATA_DURATION

    if (start > end) {
        throw new IllegalArgumentException("Start time must be less than or equal to end time");
    }

    while (start < end) {
        long nextEnd = Math.min(start + fetchDuration, end);
        timeRanges.add(new TimeRange(start, nextEnd));
        start = nextEnd;
    }

    return timeRanges;
}

