long function(long timeBucket, int dayStep) {
    try {
        long day = timeBucket / 10000L;
        int month = (int) (timeBucket / 100L) % 100;
        int year = (int) (timeBucket / 100000000L);

        int newDay = 1;
        if (dayStep % 7 == 0) {
            while (day != newDay) {
                day--;
                if (day == 0) {
                    if (month == 1) {
                        month = 12;
                        year--;
                    } else {
                        month--;
                    }
                    day = (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) ? 29 : (month == 2) ? 28 : (month == 4 || month == 6 || month == 9 || month == 11) ? 30 : 31;
                } else {
                    newDay = 1;
                }
            }
        } else {
            newDay = day + 3 * (dayStep % 7);
        }

        if (newDay > (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) ? 29 : (month == 2) ? 28 : (month == 4 || month == 6 || month == 9 || month == 11) ? 30 : 31) {
            dayStep++;
            newDay = 1;
        }

        if (month == 1 && newDay > 31) {
            month = 12;
            year--;
        }

        if (month < 10) {
            month = 100 + month;
        }

        if (newDay < 10) {
            newDay = 100 + newDay;
        }

        return year * 100000000L + month * 100L + newDay;
    } catch (ArithmeticException e) {
