static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }

    String dateStr = String.format("%08d", timeBucket);
    int year = Integer.parseInt(dateStr.substring(0, 4));
    int month = Integer.parseInt(dateStr.substring(4, 6));
    int day = Integer.parseInt(dateStr.substring(6, 8));

    switch (dayStep) {
        case 1: // Close to the start of the month
            if (day <= dayStep) {
                return Long.parseLong(String.format("%04d%02d%02d", year, month, 1));
            } else {
                return Long.parseLong(String.format("%04d%02d%02d", year, month, day - (day - 1) % dayStep));
            }
        case 7: // Close to the start of the week
            int dayOfWeek = (day - 1 + 52 * 7) % 7; // Adjusting from 1-based to 0-based
            return Long.parseLong(String.format("%04d%02d%02d", year, month, day - dayOfWeek));
        case 30: // Close to the start of the month (approximation)
            return Long.parseLong(String.format("%04d%02d%02d", year, month, Math.floorDay(day - (day - 1) % 30, ChronoUnit.DAYS)));
        default:
            int remainder = day % dayStep;
            return Long.parseLong(String.format("%04d%02d%02d", year, month, day - remainder));
    }
}
