public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || index >= str.length()) {
        throw new IllegalArgumentException("Index out of bounds");
    }
    if (len < 0 || (index + len) > str.length()) {
        throw new IllegalArgumentException("Invalid length");
    }

    int size = 0;
    for (int i = 0; i < len; i++) {
        char ch = str.charAt(index + i);
        if ((ch & 0x80) == 0) {
            size++; // 1-byte character
        } else if ((ch & 0xE0) == 0xC0) {
            size += 2; // 2-byte character
        } else if ((ch & 0xF0) == 0xE0) {
            size += 3; // 3-byte character
        } else if ((ch & 0xF8) == 0xF0) {
            size += 4; // 4-byte character
        } else {
            // Invalid UTF-16 character
            throw new IllegalArgumentException("Invalid UTF-16 character at index " + (index + i));
        }
    }
    return size;
}
