        @Override
        public T set(int index, T element) {
            if (index >= 0 && index < a.length) {
                T oldValue = a[index];
                a[index] = element;
                return oldValue;
            } else {
                throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + a.length);
            }
        }

        @Override
