public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || session == null || lb == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    try {
        byte[] utf8Bytes = str.toString().getBytes("UTF-8");
        if (utf8Bytes.length > lb.getLimit()) {
            return LinkedBuffer.allocate(lb.getCapacity() * 2);
        }

        System.arraycopy(utf8Bytes, 0, lb.getUnsafeBuffer(), lb.getOffset(), utf8Bytes.length);
        lb.setOffset(lb.getOffset() + utf8Bytes.length);
        return lb;
    } catch (UnsupportedEncodingException e) {
        // UTF-8 should be supported, but if not, throw an exception
        throw new RuntimeException("UTF-8 encoding is not supported", e);
    }
}

