public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }

    double x = box.getMinX();
    double y = box.getMinY();
    double width = box.getWidth() / 2;
    double height = box.getHeight();

    Box2D box1 = new Box2D(x, y, width, height);
    Box2D box2 = new Box2D(x + width, y, width, height);

    return Pair.with(box1, box2);
}

