public void readFrom(final InputStream in) throws IOException {
    byte[] buffer = new byte[READ_CHUNK_SIZE];
    int bytesRead;

    // Clear the buffer
    Arrays.fill(buffer, (byte) 0);

    // Reset the read pointer
    readPointer = 0;

    while ((bytesRead = in.read(buffer)) != -1) {
        // Copy bytesRead bytes from buffer to the internal buffer
        System.arraycopy(buffer, 0, this.buffer, readPointer, bytesRead);
        readPointer += bytesRead;
    }

    // Ensure the buffer is not larger than necessary
    byte[] tempBuffer = new byte[readPointer];
    System.arraycopy(this.buffer, 0, tempBuffer, 0, readPointer);
    this.buffer = tempBuffer;
}
