private Map<String, Object> buildContent(JsonObject jsonObject) {
    Map<String, Object> content = new HashMap<>();
    for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
        String key = entry.getKey();
        JsonElement value = entry.getValue();
        if (value instanceof JsonObject) {
            content.put(key, buildContent((JsonObject) value));
        } else if (value instanceof JsonArray) {
            content.put(key, buildArray((JsonArray) value));
        } else {
            content.put(key, value.getAsString());
        }
    }
    return content;
}

private List<Object> buildArray(JsonArray jsonArray) {
    List<Object> array = new ArrayList<>();
    for (JsonElement element : jsonArray) {
        if (element instanceof JsonObject) {
            array.add(buildContent((JsonObject) element));
        } else if (element instanceof JsonArray) {
            array.add(buildArray((JsonArray) element));
        } else {
            array.add(element.getAsString());
        }
    }
    return array;
}
