final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    try {
        if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
            throw new IllegalArgumentException("Invalid constant pool entry index");
        }

        int index = constantPoolEntryIndex + 1; // Size of the CONSTANT_Utf8 entry (1 byte for tag, 2 bytes for length)

        short utfLength = (short) ((classFileBuffer[index++] << 8) | classFileBuffer[index++]);
        if (utfLength >= charBuffer.length) {
            throw new IllegalArgumentException("Char buffer is too small for the UTF-8 string");
        }

        for (int i = 0; i < utfLength; i++) {
            charBuffer[i] = (char) ((classFileBuffer[index++] << 8) | classFileBuffer[index++]);
        }

        return new String(charBuffer, 0, utfLength);
    } catch (Exception e) {
        e.printStackTrace();
        return null;
    }
}
