final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    if (constantPoolEntryIndex < 1 || constantPoolEntryIndex >= classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index");
    }
    if (charBuffer == null || charBuffer.length == 0) {
        throw new IllegalArgumentException("Char buffer must be non-null and non-empty");
    }

    int offset = getConstantPoolEntry(constantPoolEntryIndex);
    if (offset == -1) {
        throw new IllegalArgumentException("Invalid CONSTANT_Utf8 entry at index: " + constantPoolEntryIndex);
    }

    int utf8Length = classFileBuffer[offset++];
    if (utf8Length > charBuffer.length) {
        throw new IllegalArgumentException("Char buffer is not large enough to hold the string");
    }

    for (int i = 0; i < utf8Length; i++) {
        charBuffer[i] = (char) classFileBuffer[offset++];
    }

    return new String(charBuffer, 0, utf8Length);
}
