import java.util.*;

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> pathEdges = new ArrayList<>(tour);
    V currentNode = null;
    V nextNode = null;

    for (E edge : pathEdges) {
        Set<E> incidentEdges = graph.edgesOf(edge.getSource());
        if (currentNode == null) {
            currentNode = edge.getSource();
        } else if (currentNode.equals(edge.getSource())) {
            nextNode = edge.getTarget();
        } else if (currentNode.equals(edge.getTarget())) {
            nextNode = edge.getSource();
        } else {
            return null; // Invalid tour
        }
        pathEdges.remove(edge);
        if (!incidentEdges.contains(currentNode)) return null; // Invalid tour
    }

    return graph.getPath(currentNode, nextNode);
}

