protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null || tour.isEmpty()) {
        return null;
    }

    Iterator<E> iterator = tour.iterator();
    E firstEdge = iterator.next();
    V startVertex = firstEdge.getSource();
    V endVertex = firstEdge.getTarget();
    List<E> edgeList = new ArrayList<>();
    edgeList.add(firstEdge);

    while (iterator.hasNext()) {
        E nextEdge = iterator.next();
        if (nextEdge.getSource().equals(endVertex)) {
            edgeList.add(nextEdge);
            endVertex = nextEdge.getTarget();
        }
    }

    if (!startVertex.equals(endVertex)) {
        throw new IllegalArgumentException("The tour does not form a valid cycle.");
    }

    return graph.createPath(edgeList);
}
