protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    if (tour.isEmpty()) {
        return graph.createEmptyPath();
    }

    Iterator<E> iterator = tour.iterator();
    E firstEdge = iterator.next();
    V source = graph.getEdgeSource(firstEdge);
    V target = graph.getEdgeTarget(firstEdge);

    GraphPath<V, E> path = graph.createPath();
    path.addVertex(source);

    while (iterator.hasNext()) {
        E edge = iterator.next();
        try {
            path.addEdge(edge);
        } catch (GraphPathNotFoundException e) {
            // Edge not found in the graph, return the path constructed so far
            break;
        }
    }

    // Ensure the path is a closed loop
    if (!graph.containsEdge(source, target)) {
        path.addVertex(target);
    }

    return path;
}

