int addConstantNameAndType(final String name, final String descriptor) {
    int nameIndex = findUtf8(name);
    int descriptorIndex = findUtf8(descriptor);

    if (nameIndex == NOT_FOUND || descriptorIndex == NOT_FOUND) {
        return NOT_FOUND;
    }

    int index = findNameAndType(nameIndex, descriptorIndex);
    if (index != NOT_FOUND) {
        return index;
    }

    int newIndex = maxPoolSize++;
    types[newIndex] = NAME_TYPE;
    utf8s[newIndex] = nameIndex;
    utf8s[newIndex + 1] = descriptorIndex;

    return newIndex;
}
