int addConstantNameAndType(final String name, final String descriptor) {
    for (int i = 0; i < constantPool.length; i++) {
        final var info = constantPool[i];
        if (info != null && info.type == CONSTANT_NameAndType_info && info.name.equals(name) && info.descriptor.equals(descriptor)) {
            return i;
        }
    }
    final int index = nextIndex();
    constantPool[index] = new CONSTANT_NameAndType_info(name, descriptor);
