private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Retrieve the bucket with the minimum label
    Set<Integer> minBucket = bucketsByLabel.get(minLabel);

    // Clear the bucket with the minimum label
    minBucket.clear();

    // Iterate over the labels to update the bucket assignments
    for (int i = 1; i < bucketsByLabel.size(); i++) {
        for (int vertex : bucketsByLabel.get(i)) {
            // Calculate the new label for the vertex
            labels.set(vertex, i);
        }
    }

    // Move all vertices from the bucket with the minimum label to the bucket with label 0
    bucketsByLabel.get(0).addAll(minBucket);

    // Update the bucket for each vertex
    for (int vertex : bucketsByLabel.get(0)) {
        labels.set(vertex, 0);
    }
}
