private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Invalid minLabel: " + minLabel);
    }
    if (bucketsByLabel.get(minLabel).isEmpty()) {
        throw new IllegalArgumentException("Bucket with minLabel is empty");
    }

    Set<Integer> minLabelBucket = bucketsByLabel.get(minLabel);
    while (!minLabelBucket.isEmpty()) {
        int vertex = minLabelBucket.iterator().next();
        int newLabel = labels.get(vertex);
        bucketsByLabel.get(newLabel).add(vertex);
        minLabelBucket.remove(vertex);
    }

    labels.set(minLabel, 0);
    bucketsByLabel.set(minLabel, new HashSet<>());
}

