private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(UndirectedGraph<Integer,E> graph) {
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();
    for (E edge : graph.edges()) {
        int v = edge.either();
        int w = edge.other(v);
        List<Pair<Integer,Integer>> separators = computeMinimialSeparators(graph, edge);
        globalSeparatorList.add(new Pair<>(separators, edge));
    }
    return globalSeparatorList;
}

private List<Pair<Integer,Integer>> computeMinimialSeparators(UndirectedGraph<Integer,E> graph, E edge) {
    List<Pair<Integer,Integer>> separators = new ArrayList<>();
    int v = edge.either();
    int w = edge.other(v);
    List<Integer> neighborhoodV = new ArrayList<>(graph.adjacentVertices(v));
    List<Integer> neighborhoodW = new ArrayList<>(graph.adjacentVertices(w));
    neighborhoodV.removeAll(neighborhoodW);
    for (Integer vertex : neighborhoodV) {
        List<Integer> separator = new ArrayList<>(graph.adjacentVertices(vertex));
        separator.removeAll(neighborhoodW);
        separators.add(new Pair<>(separator, edge));
    }
    return separators;
}
