    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparators = new ArrayList<>();
    for (E edge : graph.edges()) {
        List<List<Pair<Integer,Integer>>> minimalSeparators = new ArrayList<>();
        for (int u : graph.adjacentTo(edge)) {
            List<Pair<Integer,Integer>> separator = new ArrayList<>();
            for (int v : graph.adjacentTo(u)) {
                if (!graph.hasEdge(u, v) && !separator.contains(new Pair<>(v, u))) {
                    separator.add(new Pair<>(v, u));
                }
            }
            minimalSeparators.add(separator);
        }
        globalSeparators.add(new Pair<>(minimalSeparators.stream().flatMap(List::stream).collect(Collectors.toList()), edge));
    }
    return globalSeparators;
}

