private Set<Integer> getMinimalSeparator(int v, int w, int u) {
    Set<Integer> separator = new HashSet<>();
    for (Integer vNeighbor : adj[v]) {
        if (!vNeighbor.equals(w) && !vNeighbor.equals(u)) {
            for (Integer wNeighbor : adj[w]) {
                if (!wNeighbor.equals(v) && !wNeighbor.equals(u) && !wNeighbor.equals(vNeighbor)) {
                    for (Integer uNeighbor : adj[u]) {
                        if (!uNeighbor.equals(v) && !uNeighbor.equals(w) && !uNeighbor.equals(vNeighbor) && !uNeighbor.equals(wNeighbor)) {
                            if (isReachable(v, uNeighbor) && isReachable(w, uNeighbor)) {
                                separator.add(uNeighbor);
                            }
                        }
                    }
                }
            }
        }
    }
    return separator.stream().filter(x -> !adj[x].contains(v) || !adj[x].contains(w)).collect(Collectors.toSet());
}

private boolean isReachable(int from, int to) {
    boolean[] visited = new boolean[graph.getVertices().size()];
    Stack<Integer> stack = new Stack<>();
    stack.push(from);
    visited[from] = true;
    while (!stack.isEmpty()) {
        int current = stack.pop();
        for (Integer neighbor : adj[current]) {
            if (neighbor.equals(to)) {
                return true;
            }
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                stack.push(neighbor);
            }
        }
    }
    return false;
}
