private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    char typeChar = descriptor.charAt(0);

    if (typeChar == 'L' || typeChar == '[') {
        // This is an Object or array type. Pop a single entry from the stack.
        pop();
    } else {
        // The descriptor is a type. Pop as many entries as there are argument types.
        int argumentCount = countArgumentTypes(descriptor);
        for (int i = 0; i < argumentCount; i++) {
            pop();
        }
    }
}

