private int countArgumentTypes(String descriptor) {
    int argumentCount = 0;
    int index = 1; // Start after the initial 'L' or '['.

    while (index < descriptor.length()) {
        char typeChar = descriptor.charAt(index);

        if (typeChar == ')') {
            break;
        } else if (typeChar == 'L' || typeChar == '[') {
            // Skip object reference or array elements.
            while (index < descriptor.length() && descriptor.charAt(index) != ';') {
                index++;
            }
        }

        argumentCount++;
        index++;
    }

    return argumentCount;
}
