        if (path == null || relativePath == null) {
            throw new IllegalArgumentException("Path and relative path cannot be null");
        }

        // Split the path into components
        String[] pathComponents = path.split("/");
        // Split the relative path into components
        String[] relativeComponents = relativePath.split("/");

        int i = 0;
        // Move up the directory tree for ".."
        while (i < relativeComponents.length && relativeComponents[i].equals("..")) {
            if (pathComponents.length > 1) {
                pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
            } else {
                throw new IllegalArgumentException("Relative path tries to go above the root directory");
            }
            i++;
        }

        // Append the remaining components of the relative path
        for (; i < relativeComponents.length; i++) {
            if (!relativeComponents[i].isEmpty()) {
                pathComponents = Arrays.copyOf(pathComponents, pathComponents.length + 1);
                pathComponents[pathComponents.length - 1] = relativeComponents[i];
            }
        }

        // Join the components back into a single path
        return String.join("/", pathComponents);
    }
