public int readTag() throws IOException {
    if (buffer == null || bufferPos == bufferLimit) {
        // Read the next byte from the input stream
        int firstByte = in.read();
        if (firstByte == -1) {
            // EOF reached
            return 0;
        }
        buffer = new byte[WireFormat.MAX_VARINT_SIZE];
        buffer[0] = (byte) firstByte;
        bufferPos = 1;
        bufferLimit = 1;
    }

    // Read the tag number
    int tag = WireFormat.readTag(buffer, bufferPos);
    bufferPos += WireFormat.getTagSize(tag);

    return tag;
}
