public int readTag() throws IOException {
    try {
        int b1 = in.read();
        if (b1 == -1) {
            return 0;
        }
        int tag = (b1 & 0x7F) << 3;
        int b2 = in.read();
        if (b2 == -1) {
            throw new IOException("EOF occurred, but expected a continuation byte in tag");
        }
        tag |= b2 & 0x7F;
        while (((b2 & 0x80) != 0)) {
            b2 = in.read();
            if (b2 == -1) {
                throw new IOException("EOF occurred, but expected a continuation byte in tag");
            }
            tag = (tag << 7) | (b2 & 0x7F);
        }
        return tag;
    } catch (IOException e) {
        throw new IOException("Error reading tag", e);
    }
}
